class DailyCap(Rule):
    type_name = "daily_cap"

    def after_agent(self, ctx, agent_id, record_entry):
        # Ensure harvested_kg does not exceed 15 kg per day
        max_kg = self.params.get("max_kg", 15.0)
        harvested = record_entry.get("harvested_kg", 0.0)
        if harvested > max_kg:
            excess = harvested - max_kg
            # Apply fine 10% of excess for next day's quota
            fine = excess * 0.10
            # Store fine in rule_state keyed by agent
            ctx.rule_state(f"fine_{agent_id}")["fine"] = fine
            record_entry["harvested_kg"] = max_kg
            note = f"Harvest reduced to {max_kg}kg limit; {excess:.1f}kg excess returned to pot. Fine {fine:.1f}kg applied to next day's quota."
